# Expected values generated by test/scipy/gen_stats_final_sobol.py (scipy 1.18.1).
import numpy as np
import scipy.stats as st
from scipy.stats import uniform

def f(x):
    return np.sin(x[0]) + 7 * np.sin(x[1]) ** 2 + 0.1 * (x[2] ** 4) * np.sin(x[0])

@test
def test_sobol_indices():
    dists = [uniform(loc=-np.pi, scale=2 * np.pi), uniform(loc=-np.pi, scale=2 * np.pi), uniform(loc=-np.pi, scale=2 * np.pi)]
    r = st.sobol_indices(func=f, n=1024, dists=dists, rng=np.random.default_rng(1))
    e1 = [0.3071890195549883, 0.44519402241510336, -0.004016524211816246]
    et = [0.557346233778102, 0.4442081580933148, 0.2485676077093924]
    for i in range(3):
        assert abs(float(r.first_order[i]) - e1[i]) < 1e-6
        assert abs(float(r.total_order[i]) - et[i]) < 1e-6
